#include <bits/stdc++.h>
using namespace std;

// set version — stores {dist, node} in ascending order (TUF G-33 style)
vector<long long> dijkstra_set(int n, vector<array<int,3>> edges, int src = 0) {
    vector<vector<pair<int,int>>> g(n);
    for (auto [u, v, w] : edges) g[u].push_back({v, w});
    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    dist[src] = 0;
    set<pair<long long,int>> st;
    st.insert({0, src});
    while (!st.empty()) {
        auto [d, u] = *st.begin();
        st.erase(st.begin());
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (d + w < dist[v]) {
                st.erase({dist[v], v});
                dist[v] = d + w;
                st.insert({dist[v], v});
            }
        }
    }
    return dist;
}

// priority_queue version — also fine
vector<long long> dijkstra_pq(int n, vector<array<int,3>> edges, int src = 0) {
    vector<vector<pair<int,int>>> g(n);
    for (auto [u, v, w] : edges) g[u].push_back({v, w});
    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    dist[src] = 0;
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u]) if (d + w < dist[v]) {
            dist[v] = d + w;
            pq.push({dist[v], v});
        }
    }
    return dist;
}
